package com.primehr.rsp.evaluation.application;
import com.primehr.integration.administrative.*; import com.primehr.integration.humanresource.*; import com.primehr.rsp.evaluation.api.CommitteeDtos.MemberInput; import com.primehr.rsp.evaluation.domain.CommitteeMember; import com.primehr.security.RspCandidateEvaluationPermissionGuard; import org.springframework.security.access.AccessDeniedException; import org.springframework.stereotype.*; import java.util.*;
@Service public class CommitteeMemberEligibilityService {private final HumanResourceEmployeeDirectoryClient employees;private final AdministrativeAuthorizationClient authorization;public CommitteeMemberEligibilityService(HumanResourceEmployeeDirectoryClient e,AdministrativeAuthorizationClient a){employees=e;authorization=a;}public void validate(List<MemberInput> members,String token){Set<String> unique=new HashSet<>();for(MemberInput m:members){String key=m.employeeNo().trim().toUpperCase(Locale.ROOT);if(!unique.add(key))throw new IllegalArgumentException("An employee may appear only once in a committee version");var employee=employees.require(m.employeeNo(),token);var p=authorization.resolveEmployee(RspCandidateEvaluationPermissionGuard.FEATURE,employee.employeeNo(),employee.role(),token);boolean action=switch(m.role()){case CHAIRPERSON->p.canFinalize();case VICE_CHAIRPERSON,MEMBER,ALTERNATE->p.canAssess();case SECRETARIAT->p.canAdd()&&p.canEdit();case OBSERVER->true;};if(!p.administrator()&&(!p.canAccess()||!action||p.dataScope()!=PermissionDataScope.AGENCY_WIDE))throw new AccessDeniedException("Committee member "+m.employeeNo()+" lacks the required candidate-evaluation permission for "+m.role());}}}
